package io.aetheris.orchestrator.trading;
import org.springframework.stereotype.Service;import java.util.*;
@Service public class PaperRiskOfficerService {private final PaperRiskPolicyRepository paperPolicies;private final PaperPositionRepository positions;private final TradingIntelligenceService intelligence;public PaperRiskOfficerService(PaperRiskPolicyRepository paperPolicies,PaperPositionRepository positions,TradingIntelligenceService intelligence){this.paperPolicies=paperPolicies;this.positions=positions;this.intelligence=intelligence;}public PaperRiskPolicyEntity policy(){return paperPolicies.findById("default").orElseGet(()->paperPolicies.save(new PaperRiskPolicyEntity("default")));}public PaperRiskPolicyEntity update(PaperRiskPolicyRequest r){PaperRiskPolicyEntity p=policy();p.update(r);return paperPolicies.save(p);}public PaperRiskDecision evaluate(PaperAccountEntity account,TradeSignalEntity signal,double fill){PaperRiskPolicyEntity pp=policy();TradingRiskPolicyEntity rp=intelligence.policy();List<String> reasons=new ArrayList<>();List<PaperPositionEntity> open=positions.findByStatus(PaperPositionStatus.OPEN);if(signal.getStatus()!=TradeSignalStatus.ACCEPTED_ANALYSIS)reasons.add("Signal analysis has not been explicitly accepted");if(signal.getSide()==TradeSide.NO_TRADE)reasons.add("NO_TRADE signal cannot open a paper position");if(signal.getStopLoss()<=0)reasons.add("Stop loss is required");if(signal.getLeverage()>rp.getMaxLeverage())reasons.add("Leverage exceeds deterministic risk policy");if(signal.getRewardRisk()<rp.getMinRewardRisk())reasons.add("Reward:risk is below policy minimum");if(open.size()>=pp.getMaxOpenPositions())reasons.add("Maximum open positions reached");account.ensureDay();double dailyLossPct=account.getStartingBalance()<=0?0:Math.max(0,-account.getDailyRealizedPnl()/account.getStartingBalance()*100);if(dailyLossPct>=rp.getMaxDailyLossPct())reasons.add("Daily loss limit reached");double candidate=Math.min(signal.getRecommendedNotional(),account.getCashBalance()*signal.getLeverage());double gross=open.stream().mapToDouble(PaperPositionEntity::getNotional).sum()+candidate;if(gross>account.getCashBalance()*pp.getMaxGrossExposureMultiple())reasons.add("Gross exposure limit exceeded");double sameSymbol=open.stream().filter(p->p.getSymbol().equals(signal.getSymbol())).mapToDouble(PaperPositionEntity::getNotional).sum()+candidate;if(sameSymbol>account.getCashBalance()*pp.getMaxSymbolExposurePct()/100)reasons.add("Per-symbol exposure limit exceeded");String group=group(signal.getSymbol());double correlated=open.stream().filter(p->group(p.getSymbol()).equals(group)).mapToDouble(PaperPositionEntity::getNotional).sum()+candidate;double correlatedCap=account.getCashBalance()*pp.getMaxGrossExposureMultiple()*pp.getMaxCorrelatedExposurePct()/100;if(correlated>correlatedCap)reasons.add("Correlated exposure limit exceeded");return new PaperRiskDecision(reasons.isEmpty(),List.copyOf(reasons),gross,correlated);}private String group(String symbol){String s=symbol.toUpperCase(Locale.ROOT);for(String quote:List.of("USDT","USDC","USD","EUR","BTC"))if(s.endsWith(quote)&&s.length()>quote.length())return s.substring(0,s.length()-quote.length());return s;}}
